    cards: null,
    xstatus: [['chat', 'чищу иголку'], ['online', 'слушаю коллекцию'], ['chat', 'подбираю тебе трек'], ['online', 'сторона B'], ['away', 'перематываю кассету карандашом']],
    topics: [[/(кино|фильм|сериал)/, ['Кино слушаю ушами: хороший саундтрек — половина фильма. Что добавил в «Кино» — оценю звук.']], [/(евродэнс|eurodance)/, ['Евродэнс — это когда 140 ударов и не стыдно. Поставить «Лето 1999»?']], [/(техно|techno)/, ['Техно — честная музыка: ритм и ничего лишнего. «Дискотека 99» как раз.']], [/(баллад|медляк)/, ['Баллады — для вечера и воспоминаний. «Кассета» Ленки — прямо туда.']], [/(лаунж|lounge|джаз)/, ['Лаунж — мой любимый фон для разговоров. «Пейджер молчит» послушай.']], [/(рок|rock|гитар)/, ['Рок — «Карась» Бати. Сам сочинил на баяне, но звучит как гараж.']], [/(8 бит|чиптюн|денди|спектрум)/, ['8 бит! «Синий экран» Вовы и «Цветочек». Ностальгия в чистом виде.']], [/(яндекс|ютуб|youtube|ссылк)/, ['Вставляй ссылку во вкладке «Коллекция» → «Добавить по ссылке». Яндекс Музыка, YouTube, SoundCloud и mp3 играют прямо тут.']], [/(нфт|nft)/, ['У каждого трека НФТ с номером и владельцем. Можно подарить — кнопка 🎁 в коллекции.']]],
